import { promises as fs } from "node:fs";
import path from "node:path";
import os from "node:os";

// 不嵌独立 LLM 客户端:读 FanBox 的 ~/.fanbox/config.json,
// 用 fetch 调 OpenAI 兼容接口。key/baseURL/model 全用 FanBox 那一份。

const CONFIG_FILE = path.join(os.homedir(), ".fanbox", "config.json");

interface LlmConfig {
  baseUrl: string;
  apiKey: string;
  model: string;
}

async function readLlmConfig(): Promise<LlmConfig> {
  let cfg: Record<string, unknown> = {};
  try {
    cfg = JSON.parse(await fs.readFile(CONFIG_FILE, "utf-8"));
  } catch {
    // 无配置,下面校验后报错
  }
  return {
    baseUrl: String(cfg.chatApiBaseUrl ?? "").replace(/\/+$/, ""),
    apiKey: String(cfg.chatApiKey ?? ""),
    model: String(cfg.chatApiModel ?? ""),
  };
}

export class MissingApiKeyError extends Error {
  constructor() {
    super("尚未配置 LLM:请在 FanBox 对话窗设置里填写 API 地址 / Key / 模型。");
    this.name = "MissingApiKeyError";
  }
}

// 一次性 JSON 补全:工具内部用(校对/抽取),非流式,直接解析 JSON。
export async function completeJson<T>(opts: {
  system: string;
  user: string;
  mode?: string;
  maxTokens?: number;
}): Promise<T> {
  const { baseUrl, apiKey, model } = await readLlmConfig();
  if (!baseUrl || !apiKey || !model) throw new MissingApiKeyError();

  const body = {
    model,
    max_tokens: opts.maxTokens ?? 3000,
    temperature: opts.mode === "pro" ? 1 : 0.6,
    response_format: { type: "json_object" },
    messages: [
      { role: "system", content: opts.system },
      { role: "user", content: opts.user },
    ],
  };

  const r = await fetch(`${baseUrl}/chat/completions`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify(body),
  });

  if (!r.ok) {
    const t = await r.text().catch(() => "");
    throw new Error(`LLM API ${r.status}: ${t.slice(0, 300)}`);
  }

  const data = (await r.json()) as {
    choices?: { message?: { content?: string } }[];
  };
  const content = data.choices?.[0]?.message?.content ?? "";
  return JSON.parse(content) as T;
}

