// ===== Excel 校对面板（copilot 校对核心深度整合：选文件 → 配置 → 九列差异表）=====
function proofEsc(s) {
  return String(s == null ? '' : s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
}
const proof = {
  el: null,
  step: 1,
  baselinePath: '', targetPath: '',
  baselineSheets: [], targetSheets: [],
  baselineSheet: '', targetSheet: '',
  pairingMode: 'row', baselineKeyCol: '', targetKeyCol: '',
  relationship: 'translation',
  dimensions: ['accuracy', 'scope', 'consistency', 'sync'],
  busy: false, error: '', result: null,

  DIMS: [
    { key: 'accuracy', label: '准确性', required: true },
    { key: 'scope', label: '范围', required: true },
    { key: 'consistency', label: '一致性', required: false },
    { key: 'sync', label: '同步', required: false },
    { key: 'tone', label: '语气', required: false },
  ],
  RELATIONSHIPS: [
    { key: 'translation', label: '翻译(中→外)' },
    { key: 'same_lang_version', label: '同语言不同版本' },
    { key: 'template_fill', label: '模板 vs 填写版' },
  ],

  open() { this.el = $('#proof-overlay'); this.el.classList.remove('hidden'); this.render(); },
  close() { if (this.el) this.el.classList.add('hidden'); },

  async pick(which) {
    let p = '';
    try {
      if (window.fanboxDialog && window.fanboxDialog.pickFile) {
        p = await window.fanboxDialog.pickFile((typeof state !== 'undefined' && (state.cwd || state.home)) || '');
      } else {
        p = window.prompt('粘贴 Excel 文件的本地绝对路径');
      }
    } catch { /* 取消 */ }
    if (!p) return;
    if (which === 'baseline') this.baselinePath = p; else this.targetPath = p;
    await this.inspect(which);
    this.render();
  },

  async inspect(which) {
    const fp = which === 'baseline' ? this.baselinePath : this.targetPath;
    if (!fp) return;
    this.error = '';
    const r = await apiPost('/api/copilot/proofread/inspect', { path: fp });
    if (r.error) { this.error = r.error; return; }
    const sheets = r.sheets || [];
    if (which === 'baseline') { this.baselineSheets = sheets; this.baselineSheet = (sheets[0] || {}).name || ''; }
    else { this.targetSheets = sheets; this.targetSheet = (sheets[0] || {}).name || ''; }
  },

  toggleDim(key) {
    const d = this.DIMS.find((x) => x.key === key);
    if (d && d.required) return;
    this.dimensions = this.dimensions.includes(key) ? this.dimensions.filter((x) => x !== key) : [...this.dimensions, key];
    this.render();
  },

  async toConfig() {
    if (!this.baselinePath || !this.targetPath) return;
    if (!this.baselineSheets.length) await this.inspect('baseline');
    if (!this.targetSheets.length) await this.inspect('target');
    this.step = 2; this.render();
  },

  async run() {
    if (!this.baselinePath || !this.targetPath) return;
    this.busy = true; this.error = ''; this.result = null; this.render();
    const config = {
      baselineSheet: this.baselineSheet,
      targetSheet: this.targetSheet,
      pairingMode: this.pairingMode,
      baselineKeyCol: this.pairingMode === 'key' ? (Number(this.baselineKeyCol) || undefined) : undefined,
      targetKeyCol: this.pairingMode === 'key' ? (Number(this.targetKeyCol) || undefined) : undefined,
      relationship: this.relationship,
      dimensions: this.dimensions,
    };
    let r;
    try {
      r = await apiPost('/api/copilot/proofread/run', { baselinePath: this.baselinePath, targetPath: this.targetPath, config });
    } catch (e) { r = { ok: false, error: String((e && e.message) || e) }; }
    this.busy = false;
    if (r.ok && r.canvas && r.canvas.data) { this.result = r.canvas.data; this.step = 3; }
    else { this.error = r.error || r.summary || '校对失败'; }
    this.render();
  },

  sheetCols(which) {
    const list = which === 'baseline' ? this.baselineSheets : this.targetSheets;
    const name = which === 'baseline' ? this.baselineSheet : this.targetSheet;
    return (list.find((s) => s.name === name) || {}).columns || [];
  },

  renderLeft() {
    const e = proofEsc;
    if (this.step === 1) {
      const row = (which, label, val) => `
        <div class="pf-field">
          <label>${label}</label>
          <div class="pf-pathrow">
            <input class="pf-input" data-path="${which}" value="${e(val)}" placeholder="Excel 绝对路径（.xlsx/.xls）" />
            <button class="pf-btn" data-act="pick-${which}">选择</button>
          </div>
        </div>`;
      return row('baseline', '母本（标准 / 事实依据）', this.baselinePath)
        + row('target', '目标（被校对）', this.targetPath)
        + `<button class="pf-primary" data-act="to-config" ${this.baselinePath && this.targetPath ? '' : 'disabled'}>下一步：配置</button>`;
    }
    if (this.step === 2) {
      const sheetSel = (which, val, list) => `
        <div class="pf-field"><label>${which === 'baseline' ? '母本' : '目标'} sheet</label>
          <select class="pf-sel" data-field="${which}Sheet">
            ${list.map((s) => `<option value="${e(s.name)}" ${s.name === val ? 'selected' : ''}>${e(s.name)}</option>`).join('')}
          </select></div>`;
      const keySel = (which) => `
        <div class="pf-field"><label>${which === 'baseline' ? '母本' : '目标'}关键列</label>
          <select class="pf-sel" data-field="${which}KeyCol">
            <option value="">选择列</option>
            ${this.sheetCols(which).map((c) => `<option value="${c.index}" ${String(this[which + 'KeyCol']) === String(c.index) ? 'selected' : ''}>${e(c.letter)} · ${e(c.header || '(空表头)')}</option>`).join('')}
          </select></div>`;
      return sheetSel('baseline', this.baselineSheet, this.baselineSheets)
        + sheetSel('target', this.targetSheet, this.targetSheets)
        + `<div class="pf-field"><label>配对方式</label><div class="pf-chips">
            <button class="pf-chip ${this.pairingMode === 'row' ? 'on' : ''}" data-pair="row">按行号</button>
            <button class="pf-chip ${this.pairingMode === 'key' ? 'on' : ''}" data-pair="key">按关键列</button>
          </div></div>`
        + (this.pairingMode === 'key' ? `<div class="pf-grid2">${keySel('baseline')}${keySel('target')}</div>` : '')
        + `<div class="pf-field"><label>源-目标关系</label>
            <select class="pf-sel" data-field="relationship">
              ${this.RELATIONSHIPS.map((r) => `<option value="${r.key}" ${r.key === this.relationship ? 'selected' : ''}>${e(r.label)}</option>`).join('')}
            </select></div>`
        + `<div class="pf-field"><label>评估维度</label><div class="pf-chips">
            ${this.DIMS.map((d) => `<button class="pf-chip ${this.dimensions.includes(d.key) ? 'on' : ''}" data-dim="${d.key}">${e(d.label)}${d.required ? ' ·必选' : ''}</button>`).join('')}
          </div></div>`
        + `<div class="pf-actions">
            <button class="pf-btn" data-act="to-pick">上一步</button>
            <button class="pf-primary" data-act="run" ${this.busy ? 'disabled' : ''}>${this.busy ? '校对中…' : '开始校对'}</button>
          </div>`;
    }
    return `<p class="pf-note">校对完成，结果见右侧。</p>
      <div class="pf-actions">
        <button class="pf-btn" data-act="rerun">调整配置重跑</button>
        ${this.result && !this.result.noDifference ? '<button class="pf-btn" data-act="export">复制 Markdown</button>' : ''}
      </div>`;
  },

  renderResult() {
    const e = proofEsc;
    if (this.busy) return '<div class="pf-empty">校对中…（LLM 推理，可能数十秒）</div>';
    if (!this.result) return '<div class="pf-empty">完成配置并校对后，九列差异表显示在这里。</div>';
    if (this.result.noDifference) return `<div class="pf-empty">未发现差异。${this.result.notes ? '<br>' + e(this.result.notes) : ''}</div>`;
    const head = ['文件', '位置', '原文', '建议', '维度', '子类型', '严重度', '置信度', '依据'];
    const rows = (this.result.findings || []).map((f) => `<tr>
      <td>${e(f.file)}</td><td>${e(f.location)}</td><td>${e(f.original)}</td><td>${e(f.suggestion)}</td>
      <td>${e(f.dimension)}</td><td>${e(f.subtype)}</td><td>${e(f.severity)}</td><td>${e(f.confidence)}</td><td>${e(f.evidence)}</td>
    </tr>`).join('');
    return `${this.result.notes ? `<div class="pf-notes">${e(this.result.notes)}</div>` : ''}
      <div class="pf-tablewrap"><table class="pf-table">
        <thead><tr>${head.map((h) => `<th>${h}</th>`).join('')}</tr></thead>
        <tbody>${rows}</tbody>
      </table></div>`;
  },

  render() {
    if (!this.el) return;
    const stepBadge = (n, label) => `<span class="pf-stepbadge ${this.step === n ? 'active' : ''}">${n}.${label}</span>`;
    this.el.innerHTML = `
      <div class="pf-modal">
        <header class="pf-head">
          <span class="pf-title">Excel 校对</span>
          <span class="pf-stepper">${stepBadge(1, '选文件')}${stepBadge(2, '配置')}${stepBadge(3, '结果')}</span>
          <button class="pf-x" data-act="close" title="关闭">✕</button>
        </header>
        <div class="pf-body">
          <section class="pf-left">
            ${this.renderLeft()}
            ${this.error ? `<p class="pf-err">${proofEsc(this.error)}</p>` : ''}
          </section>
          <section class="pf-right">${this.renderResult()}</section>
        </div>
      </div>`;
    this.bind();
  },

  bind() {
    const root = this.el;
    root.querySelectorAll('[data-act]').forEach((b) => { b.onclick = () => this.onAct(b.getAttribute('data-act')); });
    root.querySelectorAll('[data-path]').forEach((inp) => { inp.onchange = () => { const w = inp.getAttribute('data-path'); if (w === 'baseline') this.baselinePath = inp.value.trim(); else this.targetPath = inp.value.trim(); }; });
    root.querySelectorAll('[data-field]').forEach((sel) => { sel.onchange = () => { this[sel.getAttribute('data-field')] = sel.value; }; });
    root.querySelectorAll('[data-pair]').forEach((b) => { b.onclick = () => { this.pairingMode = b.getAttribute('data-pair'); this.render(); }; });
    root.querySelectorAll('[data-dim]').forEach((b) => { b.onclick = () => this.toggleDim(b.getAttribute('data-dim')); });
  },

  onAct(act) {
    if (act === 'close') return this.close();
    if (act === 'pick-baseline') return this.pick('baseline');
    if (act === 'pick-target') return this.pick('target');
    if (act === 'to-config') return this.toConfig();
    if (act === 'to-pick') { this.step = 1; return this.render(); }
    if (act === 'run') return this.run();
    if (act === 'rerun') { this.step = 2; return this.render(); }
    if (act === 'export') return this.exportMd();
  },

  exportMd() {
    if (!this.result || !this.result.findings) return;
    const head = '| 文件 | 位置 | 原文 | 建议 | 维度 | 子类型 | 严重度 | 置信度 | 依据 |\n|---|---|---|---|---|---|---|---|---|';
    const rows = this.result.findings.map((f) => `| ${f.file} | ${f.location} | ${f.original} | ${f.suggestion} | ${f.dimension} | ${f.subtype} | ${f.severity} | ${f.confidence} | ${f.evidence} |`);
    const md = [head, ...rows].join('\n');
    try { navigator.clipboard.writeText(md); if (typeof toast === 'function') toast('九列表已复制为 Markdown'); }
    catch { if (typeof toast === 'function') toast('复制失败', true); }
  },
};

