let _copilot = null;
function getCopilot() {
  if (!_copilot) _copilot = require('./vendor-server/copilot.cjs');
  return _copilot;
}

// 用 cursor-agent headless（ask 模式，不动文件）跑一个 prompt，聚合最终文本。
// 给校对这种「确定性页面要一次性拿结果」用：复用 FanBox 已在用的 Agent，无需 API Key。
function runCursorHeadlessText(prompt, model) {
  return new Promise((resolve, reject) => {
    const { file, pre, shell } = resolveCursorAgent();
    const args = [...pre, '-p', prompt, '--output-format', 'stream-json', '--stream-partial-output', '--force', '--workspace', HOME, '--mode', 'ask'];
    if (model) args.push('--model', String(model));
    let child;
    try { child = spawn(file, args, { cwd: HOME, shell, env: process.env }); }
    catch (e) { return reject(e); }
    let buf = '', resultText = '', assistantText = '', errTail = '';
    const timer = setTimeout(() => { try { child.kill(); } catch { /* */ } reject(new Error('cursor-agent 超时')); }, 240000);
    child.stdout.on('data', (chunk) => {
      buf += chunk.toString('utf8');
      let nl;
      while ((nl = buf.indexOf('\n')) >= 0) {
        const line = buf.slice(0, nl).trim(); buf = buf.slice(nl + 1);
        if (!line) continue;
        let ev; try { ev = JSON.parse(line); } catch { continue; }
        if (!ev || !ev.type) continue;
        if (ev.type === 'assistant' && ev.message && Array.isArray(ev.message.content)) {
          for (const c of ev.message.content) if (c.type === 'text' && c.text) assistantText += c.text;
        } else if (ev.type === 'result') { resultText = ev.result || ''; }
      }
    });
    child.stderr.on('data', (c) => { errTail = (errTail + c.toString('utf8')).slice(-500); });
    child.on('error', (e) => { clearTimeout(timer); reject(e); });
    child.on('close', (code) => {
      clearTimeout(timer);
      const text = (resultText || assistantText || '').trim();
      if (!text) return reject(new Error(`cursor-agent 无输出（退出码 ${code}）${errTail ? '：' + errTail.trim() : '（可能未登录：终端里跑一次 cursor-agent login）'}`));
      resolve(text);
    });
  });
}

// 从 agent 自由文本里抠出 JSON 对象（去 ```json 围栏 + 取首尾花括号）。
function extractJsonObject(text) {
  let t = String(text || '').trim();
  const fence = t.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) t = fence[1].trim();
  const s = t.indexOf('{'), e = t.lastIndexOf('}');
  if (s >= 0 && e > s) t = t.slice(s, e + 1);
  return JSON.parse(t);
}

// 校对等「确定性页面」的 LLM 调用：优先用 FanBox 在用的 Agent（cursor-agent），
// 后端明确选 api、或 agent 失败且配了 API Key 时，退回直连 API。
async function copilotComplete(opts) {
  const cfg = await readConfig();
  const backend = cfg.chatBackend || 'cursor';
  const hasApi = !!(cfg.chatApiBaseUrl && cfg.chatApiKey && cfg.chatApiModel);
  if (backend !== 'api') {
    try {
      const prompt = `${opts.system}\n\n${opts.user}\n\n务必只输出一个 JSON 对象，不要任何解释、前后缀或代码围栏。`;
      const text = await runCursorHeadlessText(prompt, cfg.chatCursorModel);
      return extractJsonObject(text);
    } catch (e) {
      if (!hasApi) throw new Error('Agent（cursor-agent）调用失败：' + e.message + '。可在终端跑 cursor-agent login，或在对话窗设置里填 API Key 作为备用。');
      // 配了 API Key：退回 API
    }
  }
  const { completeJson } = getCopilot();
  return completeJson(opts);
}

